const tracePrefixes=["Scale matrix: B = A / s; s = ","Krylov block starts: ","Determinant (signed product of pivots) = ","Initial approximation: ","Iteration ","Initial x = ","Weighted sum = ","Term ","Simplified polynomial (ascending powers): ","Evaluate at x = ","Characteristic polynomial coefficients (descending powers of λ): "];
